# ------------------------------------------------------------
# 3. HELPER FUNCTIONS
# ------------------------------------------------------------

find_column <- function(data, candidates, required = FALSE) {
  
  available <- names(data)
  
  match_index <- match(
    tolower(candidates),
    tolower(available)
  )
  
  match_index <- match_index[!is.na(match_index)]
  
  if (length(match_index) > 0) {
    return(available[match_index[1]])
  }
  
  if (required) {
    stop(
      "Required column not found. Expected one of: ",
      paste(candidates, collapse = ", "),
      "\nAvailable columns: ",
      paste(available, collapse = ", ")
    )
  }
  
  NULL
}

get_numeric <- function(data, column, default = NA_real_) {
  
  if (is.null(column)) {
    return(rep(default, nrow(data)))
  }
  
  suppressWarnings(
    as.numeric(data[[column]])
  )
}

get_text <- function(data, column, default = NA_character_) {
  
  if (is.null(column)) {
    return(rep(default, nrow(data)))
  }
  
  as.character(data[[column]])
}

to_boolean <- function(x) {
  
  if (is.logical(x)) {
    return(!is.na(x) & x)
  }
  
  if (is.numeric(x)) {
    return(!is.na(x) & x != 0)
  }
  
  value <- tolower(trimws(as.character(x)))
  
  value %in% c(
    "true", "t", "1", "yes", "y", "significant"
  )
}

count_unique <- function(x) {
  length(unique(x[!is.na(x) & nzchar(as.character(x))]))
}

safe_write <- function(data, filename) {
  
  write.csv(
    data,
    file.path(tables_dir, filename),
    row.names = FALSE,
    na = ""
  )
}

# ------------------------------------------------------------
# 4. IDENTIFY CANDIDATE IDENTIFIERS
# ------------------------------------------------------------

