  ledger,
  c("network_evidence", "has_network_evidence"),
  required = FALSE
)

pathway_flag_col <- find_column(
  ledger,
  c("pathway_evidence", "has_pathway_evidence"),
  required = FALSE
)

module_flag_col <- find_column(
  ledger,
  c("module_evidence", "has_module_evidence"),
  required = FALSE
)

