  to_boolean(ledger[[significant_col]])
} else {
  NA
}

assessment$network_evidence <- if (!is.null(network_flag_col)) {
  to_boolean(ledger[[network_flag_col]])
} else {
  NA
}

assessment$pathway_evidence <- if (!is.null(pathway_flag_col)) {
  to_boolean(ledger[[pathway_flag_col]])
} else {
  NA
}

assessment$module_evidence <- if (!is.null(module_flag_col)) {
  to_boolean(ledger[[module_flag_col]])
} else {
  NA
}

