  pathway_edges$pathway_identifier,
  by = list(gene_symbol = pathway_edges$gene_symbol),
  FUN = count_unique
)

names(pathway_counts)[2] <- "unique_pathway_count"

assessment <- merge(
  assessment,
  pathway_counts,
  by = "gene_symbol",
  all.x = TRUE,
  sort = FALSE
)

assessment$unique_pathway_count[
  is.na(assessment$unique_pathway_count)
] <- 0

# ------------------------------------------------------------
# 7. MODULE SUPPORT PER CANDIDATE
# ------------------------------------------------------------

