  module_counts,
  by = "gene_symbol",
  all.x = TRUE,
  sort = FALSE
)

assessment$unique_module_count[
  is.na(assessment$unique_module_count)
] <- 0

# ------------------------------------------------------------
# 8. BIOLOGICAL EVIDENCE CLASSIFICATION
# ------------------------------------------------------------

assessment$functional_support <- ifelse(
  assessment$unique_pathway_count > 0 &
    assessment$unique_module_count > 0,
  "PATHWAY_AND_MODULE_SUPPORTED",
  ifelse(
    assessment$unique_pathway_count > 0,
    "PATHWAY_SUPPORTED",
    ifelse(
      assessment$unique_module_count > 0,
      "MODULE_SUPPORTED",
      "NO_FUNCTIONAL_ASSOCIATION"
    )
  )
)

assessment$evidence_assessment <- ifelse(
  !is.na(assessment$observed_layer_count) &
    assessment$observed_layer_count >= 4 &
    assessment$unique_pathway_count > 0 &
    assessment$unique_module_count > 0,
  "MULTILAYER_FUNCTIONAL_SUPPORT",
  ifelse(
    !is.na(assessment$observed_layer_count) &
      assessment$observed_layer_count >= 3,
    "MULTILAYER_SUPPORT",
    "LIMITED_OR_PARTIAL_SUPPORT"
  )
)

assessment$interpretation_note <- ifelse(
  assessment$evidence_assessment ==
    "MULTILAYER_FUNCTIONAL_SUPPORT",
  paste(
    "Convergent evidence across the previously defined",
    "evidence layers, with pathway and module associations."
  ),
  ifelse(
    assessment$evidence_assessment == "MULTILAYER_SUPPORT",
    "Multiple evidence layers; functional support is less complete.",
    "Evidence coverage is incomplete or functional associations are limited."
  )
)

